"use client";

import { chakra } from "@chakra-ui/react"

const Alert = chakra("div", {
  base: {
    lineHeight: "1",
    fontSize: "sm",
    fontWeight: "semibold",
    rounded: "md",
    padding: "4",
    fontFamily: "Inter",
    color: "white",
  },
  variants: {
    status: {
      default: { bg: "gray" },
      error: { bg: "red" },
      success: { bg: "green" },
      warning: { bg: "orange" },
    },
    caps: {
      true: {
        textTransform: "uppercase",
      },
    },
  },
})

export const SystemAlertRecipe = () => {
  return (
    <Alert status="success" caps>
      This is an alert
    </Alert>
  )
}

"use client";

import { Alert, For, Span, useSlotRecipe } from "@chakra-ui/react"
import { colorPalettes } from "@/components/rendyn-libraries/chakra/upstream/lib/color-palettes"
import { PlaygroundTable } from "@/components/rendyn-libraries/chakra/upstream/lib/playground-table"

export const AlertSizeTable = () => {
  const recipe = useSlotRecipe({ key: "alert" })
  return (
    <PlaygroundTable>
      <thead>
        <tr>
          <td />
          <For each={recipe.variantMap.size}>{(v) => <td key={v}>{v}</td>}</For>
        </tr>
      </thead>
      <tbody>
        <For each={colorPalettes}>
          {(c) => (
            <tr key={c}>
              <td>
                <Span fontSize="sm" color="fg.muted" minW="8ch">
                  {c}
                </Span>
              </td>
              <For each={recipe.variantMap.size}>
                {(v) => (
                  <td key={v}>
                    <AlertDemo size={v} colorPalette={c} />
                  </td>
                )}
              </For>
            </tr>
          )}
        </For>
      </tbody>
    </PlaygroundTable>
  )
}

const AlertDemo = (props: Alert.RootProps) => {
  return (
    <Alert.Root {...props}>
      <Alert.Indicator />
      <Alert.Content>
        <Alert.Title>Alert Title</Alert.Title>
        <Alert.Description>
          Chakra UI v3 is the greatest! Check it out.
        </Alert.Description>
      </Alert.Content>
    </Alert.Root>
  )
}

